// Keep only WS + CS tickets, no assignee, not excluded, not a fresh empty handoff. Max 5 per run. Skips tickets tagged nova_routing_failed.
const WS = 22616861202452, CS = 23897889259668;
const EXCLUDED = [253224, 250770, 250793];
const MAX_PER_RUN = 5; // keep each run < 5 min
const now = Date.now();
const results = $input.first().json.results || [];
const out = [];
for (const t of results) {
  if (![WS, CS].includes(t.group_id)) continue;
  if (t.assignee_id) continue;
  if (EXCLUDED.includes(t.id)) continue;
  if ((t.tags || []).includes('nova_routing_failed')) continue; // both writes failed before — a human handles it
  const ageMin = (now - new Date(t.created_at).getTime()) / 60000;
  const looksEmptyHandoff = /^Conversation with/i.test(t.description || '') && (t.tags || []).includes('ada_messaging_handoff');
  if (looksEmptyHandoff && ageMin < 10) continue; // next run picks it up once the customer has written
  const cat = (t.custom_fields || []).find(f => f.id === 22865771347348)?.value || null;
  out.push({ json: {
    ticket_id: t.id, subject: t.subject, group_id: t.group_id, status: t.status,
    requester_id: t.requester_id, created_at: t.created_at, current_category: cat,
    channel: t.via?.channel, tags: t.tags,
  }});
  if (out.length >= MAX_PER_RUN) break;
}
return out;

