={{ (() => {
  const d = $json.output || {};
  const A = { justin: 54788295418644, sudu: 24567978777492, jaime: 55350915332244, caro: 32288140085012, cristian: 48493524357268, brisa: 47071350698516, miguel: 28269839522452, samuel: 40230868739348 };
  const N = { justin: 'Justin', sudu: 'Sudu', jaime: 'Jaime', caro: 'Caro', cristian: 'Cristian', brisa: 'Brisa', miguel: 'Miguel', samuel: 'Samuel' };
  const WS = 22616861202452, CS = 23897889259668;
  if (!d.owner_key || !d.ticket_id) return JSON.stringify({ skip: true, urgent: false, error: 'Agent returned no decision' });
  const lk = $('Prepare Lookups').first().json;
  const tags = lk.tags || [];
  let o = d.owner_key; const notes = [];
  if (d.low_context && d.requester_type !== 'client') { o = 'jaime'; notes.push('Low-context ticket — assigned to Jaime per Mike.'); }
  const tagOk = tags.includes(d.category_tag);
  if (!tagOk) notes.push('Suggested category "' + d.category_name + '" not set: tag "' + d.category_tag + '" is not a valid option.');
  if (d.requester_type === 'client' && d.confidence !== 'high') notes.push("I don't have a high confidence score on what the client needs — please review, and if it's not for you, assign it to " + (o === 'miguel' ? 'Samuel' : 'Miguel') + '. Thanks! 🙌');
  if ((d.possible_duplicate_of || []).length) notes.push('Possible duplicate of #' + d.possible_duplicate_of.join(', #') + ' — please check and merge if it is; otherwise handle as a normal ticket.');
  const body = [
    '🤖 Nova · Domain routing + diagnosis (n8n AI agent) · ' + $now.setZone('America/Bogota').toFormat('dd LLL HH:mm') + ' COL',
    'Category → ' + d.category_name + ' · Owner: ' + N[o] + ' · Confidence: ' + d.confidence,
    '• Ask: ' + (d.ask || d.reason),
    '• Onsight: ' + (d.onsight_facts || d.verified_facts || 'not verified'),
    '• Side conversations: ' + (d.side_conversations || 'none'),
    '• Duplicates: ' + ((d.possible_duplicate_of || []).length ? '#' + d.possible_duplicate_of.join(', #') : 'none'),
    '• Suggested action: ' + (d.suggested_action || '-') + ' (owner: ' + N[o] + ')',
    '• Suggested reply' + (d.reply_language ? ' (' + d.reply_language + ')' : '') + ': "' + (d.suggested_reply || '') + '"',
    'Routing reason: ' + d.reason
  ].concat(notes).concat(['This is a suggestion — please validate before sending 🙌']).filter(Boolean).join('\n');
  const t = { assignee_id: A[o], comment: { public: false, body } };
  if (tagOk) t.custom_fields = [{ id: 22865771347348, value: d.category_tag }];
  if (d.requester_type === 'client') t.group_id = CS;
  const f = { assignee_id: A[o], comment: { public: false, body: body + '\n(Category could not be saved automatically — required fields missing. Please set it when working the ticket.)' } };
  if (d.requester_type === 'client') f.group_id = CS;
  return JSON.stringify({ skip: false, ticket_id: d.ticket_id, owner: N[o], category_name: d.category_name, confidence: d.confidence, urgent: !!d.urgent, urgent_reason: d.urgent_reason || '', update: { ticket: t }, fallback: { ticket: f } });
})() }}

